class Solution {
public:
    string numberToWords(int num) {
        if (num == 0) return "Zero";
        vector<string> belowTwenty = {"", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"};
        vector<string> tens = {"", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"};
        vector<string> thousands = {"", "Thousand", "Million", "Billion"};
        auto helper = [&](auto& self, int n) -> string {
            if (n == 0) return "";
            if (n < 20) return belowTwenty[n] + " ";
            if (n < 100) return tens[n / 10] + " " + self(self, n % 10);
            return belowTwenty[n / 100] + " Hundred " + self(self, n % 100);
        };
        string res = "";
        for (int i = 0; i < 4; i++) {
            if (num % 1000 != 0) {
                string part = helper(helper, num % 1000);
                string unit = thousands[i];
                if (!unit.empty()) part += unit + " ";
                res = part + res;
            }
            num /= 1000;
        }
        while (!res.empty() && res.back() == ' ') res.pop_back();
        return res;
    }
};

class Solution {
    private final String[] belowTwenty = {"", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"};
    private final String[] tens = {"", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"};
    private final String[] thousands = {"", "Thousand", "Million", "Billion"};

    public String numberToWords(int num) {
        if (num == 0) return "Zero";
        String res = "";
        for (int i = 0; i < thousands.length; i++) {
            if (num % 1000 != 0) {
                String part = helper(num % 1000);
                String unit = thousands[i];
                if (!unit.isEmpty()) part += unit + " ";
                res = part + res;
            }
            num /= 1000;
        }
        return res.trim();
    }

    private String helper(int n) {
        if (n == 0) return "";
        if (n < 20) return belowTwenty[n] + " ";
        if (n < 100) return tens[n / 10] + " " + helper(n % 10);
        return belowTwenty[n / 100] + " Hundred " + helper(n % 100);
    }
}

var numberToWords = function(num) {
    if (num === 0) return "Zero";
    const belowTwenty = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"];
    const tens = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"];
    const thousands = ["", "Thousand", "Million", "Billion"];
    const helper = (n) => {
        if (n === 0) return "";
        if (n < 20) return belowTwenty[n] + " ";
        if (n < 100) return tens[Math.floor(n / 10)] + " " + helper(n % 10);
        return belowTwenty[Math.floor(n / 100)] + " Hundred " + helper(n % 100);
    };
    let res = "";
    for (let i = 0; i < thousands.length; i++) {
        if (num % 1000 !== 0) {
            let part = helper(num % 1000);
            const unit = thousands[i];
            if (unit) part += unit + " ";
            res = part + res;
        }
        num = Math.floor(num / 1000);
    }
    return res.trim();
};
